class Solution {
public:
    string mergeAlternately(string word1, string word2) {
        int n1 = word1.size(), n2 = word2.size();
        string res;
        res.reserve(n1 + n2);
        int limit = max(n1, n2);
        for (int i = 0; i < limit; i++) {
            if (i < n1) res.push_back(word1[i]);
            if (i < n2) res.push_back(word2[i]);
        }
        return res;
    }
};
